function window({ scheduledAt, overrideDay }) {
  const n = new Date(scheduledAt);
  if (!Number.isFinite(n.getTime())) throw Error("Invalid schedule time");
  if (typeof overrideDay !== "string") throw Error("Invalid replay date");
  let start, end;
  if (overrideDay) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(overrideDay)) throw Error("Replay date must be YYYY-MM-DD");
    start = new Date(overrideDay + "T00:00:00.000Z");
    if (!Number.isFinite(start.getTime()) || start.toISOString().slice(0, 10) !== overrideDay)
      throw Error("Invalid replay date");
    end = new Date(start.getTime() + 86400000);
  } else {
    end = new Date(Date.UTC(n.getUTCFullYear(), n.getUTCMonth(), n.getUTCDate()));
    start = new Date(end.getTime() - 86400000);
  }
  const search =
    "created_at:>='" + start.toISOString() + "' created_at:<'" + end.toISOString() + "'";
  return { search, variables: { query: search } };
}

return [{ json: window({ scheduledAt: new Date().toISOString(), overrideDay: "" }) }];

function plan({ data }) {
  if (
    !data ||
    !data.orders ||
    !Array.isArray(data.orders.edges) ||
    !data.orders.pageInfo ||
    typeof data.orders.pageInfo.hasNextPage !== "boolean"
  )
    throw Error("Invalid Shopify order response");
  const rows = [];
  for (const edge of data.orders.edges) {
    const o = edge?.node;
    if (!o || typeof o.id !== "string" || !o.id || typeof o.name !== "string" || !o.name)
      throw Error("Invalid Shopify order");
    if (!Object.hasOwn(o, "customerJourneySummary")) throw Error("Missing Shopify journey");
    const j = o.customerJourneySummary;
    if (j === null) continue;
    if (typeof j !== "object" || Array.isArray(j) || typeof j.ready !== "boolean" || !j.ready)
      throw Error("Shopify attribution is not ready");
    if (!Object.hasOwn(j, "firstVisit")) throw Error("Missing first visit");
    if (j.firstVisit === null) continue;
    if (
      typeof j.firstVisit !== "object" ||
      Array.isArray(j.firstVisit) ||
      !Object.hasOwn(j.firstVisit, "utmParameters")
    )
      throw Error("Invalid first visit");
    const u = j.firstVisit.utmParameters;
    if (u === null) continue;
    if (typeof u !== "object" || Array.isArray(u)) throw Error("Invalid UTM parameters");
    if (!Object.hasOwn(u, "campaign") || !(typeof u.campaign === "string" || u.campaign === null))
      throw Error("Invalid campaign");
    if (u.campaign === null) continue;
    for (const key of ["content", "medium", "source"])
      if (!Object.hasOwn(u, key) || !(typeof u[key] === "string" || u[key] === null))
        throw Error("Invalid UTM " + key);
    const money = o.totalReceivedSet?.shopMoney;
    if (
      !money ||
      typeof money.amount !== "string" ||
      !/^\d+(?:\.\d+)?$/.test(money.amount) ||
      typeof money.currencyCode !== "string" ||
      !/^[A-Z]{3}$/.test(money.currencyCode)
    )
      throw Error("Invalid order amount");
    rows.push({
      order: o.name,
      campaign: u.campaign,
      content: u.content ?? "",
      medium: u.medium ?? "",
      source: u.source ?? "",
      revenue: money.amount,
      currency: money.currencyCode,
    });
  }
  return { rows, truncated: data.orders.pageInfo.hasNextPage };
}

const result = plan({ data: $input.first().json.data });
return result.rows.map((json, i) => ({ json, pairedItem: { item: 0 } }));

if (!Number.isSafeInteger($json.id) || $json.id <= 0)
